const t=JSON.parse(localStorage.getItem("user")||"null");t&&(document.getElementById("sidebar-user-name").textContent=t.name,document.getElementById("sidebar-user-email").textContent=t.email);document.getElementById("logout-btn").addEventListener("click",()=>{localStorage.removeItem("token"),localStorage.removeItem("user"),window.location.href="/login"});const o=document.getElementById("sidebar"),n=document.getElementById("sidebar-overlay");n&&n.addEventListener("click",()=>{o.classList.add("-translate-x-full"),n.classList.add("hidden")});document.addEventListener("astro:after-swap",()=>{const e=JSON.parse(localStorage.getItem("user")||"null");if(e){const a=document.getElementById("sidebar-user-name"),l=document.getElementById("sidebar-user-email");a&&(a.textContent=e.name),l&&(l.textContent=e.email)}});
